// Map the BigQuery result onto the column order ALREADY IN THE SHEET.
// Row 1 of the sheet is the contract: it is read at runtime, never rewritten.
// A header we cannot source yet simply comes back blank, so adding a source
// later means changing only the SQL and this one table.

const HEADER_TO_FIELD = {
  'Employee ID': 'employee_id',
  'Preferred First Name': 'preferred_first_name',
  'Preferred Last Name': 'preferred_last_name',
  'HRIS ID': 'hris_id',
  'Phone Extension': 'phone_extension',
  'Email Address': 'email_address',
  'Sam Account Name': 'sam_account_name',
  'Office Location': 'office_location',
  'Start Date': 'start_date',
  'Seniority Date': 'seniority_date',
  'Forecast End Date': 'forecast_end_date',
  'Birthday': 'birthday',
  'Work Group ID': 'work_group_id',
  'Work Group': 'work_group',
  'Employee Type': 'employee_type',
  'Employee Profile': 'employee_profile',
  'Job Title': 'job_title',
  'Level': 'level',
  "Manager's Employee ID": 'manager_employee_id',
  "Manager's Name": 'manager_name',
  "Manager's HRIS ID": 'manager_hris_id',
  "Manager's Work Group": 'manager_work_group',
  "2nd Level Manager's Employee ID": 'manager2_employee_id',
  "2nd Level Manager's Name": 'manager2_name',
  "2nd Level Manager's HRIS ID": 'manager2_hris_id',
  'Shirt Size': 'shirt_size',
  'Parent Work Group': 'parent_work_group',
  'Headcount Classification': 'headcount_classification',
  'Work Group 1': 'work_group_1',
  'Work Group 2': 'work_group_2',
  'Work Group 3': 'work_group_3',
  'Work Group 4': 'work_group_4',
  'Work Group 5': 'work_group_5',
  'Work Group 6': 'work_group_6',
  'Work Group 7': 'work_group_7',
  'Work Group 8': 'work_group_8',
  'Work Group 9': 'work_group_9',
  'Work Group 10': 'work_group_10',
};

// Sheet headers arrive with stray leading spaces and sometimes curly quotes.
const normalize = (h) => String(h == null ? '' : h)
  .replace(/[‘’]/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

const headerResponse = $('Sheets API - Read Header Row').first().json || {};
const headerRow = (headerResponse.values && headerResponse.values[0]) || [];

const rows = $input.all()
  .map((item) => item.json || {})
  .filter((row) => Object.keys(row).length > 0);

const toText = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
};

// Resolve each sheet column to a source field. Duplicated headers (the export
// repeats Preferred Last Name / Preferred First Name) resolve to the same field.
const filled = [];
const blank = [];
const plan = headerRow.map((raw) => {
  const key = normalize(raw);
  const field = HEADER_TO_FIELD[key] || null;
  if (key === '') return null;
  if (field) filled.push(key); else blank.push(key);
  return field;
});

if (headerRow.length === 0) {
  return [{ json: { row_count: 0, header_error: true, records: [],
    message: 'Row 1 of the sheet is empty. Paste the Org Browser header row into row 1 first - the workflow maps onto it and will not invent one.' } }];
}

const records = rows.map((row) => plan.map((field) => (field ? toText(row[field]) : '')));

return [{ json: {
  row_count: records.length,
  column_count: headerRow.length,
  records,
  headers_filled: [...new Set(filled)],
  headers_left_blank: [...new Set(blank)],
  header_error: false,
} }];

// One values:batchUpdate body per chunk, written from row 2 down.
// Row 1 (the header row you pasted) is never written to.
const TAB_NAME = 'Sheet1';
const CHUNK_ROWS = 5000;
const FIRST_DATA_ROW = 2;

const source = $('Code - Map Roster To Sheet Columns').first().json;
const records = source.records || [];
const chunks = [];

for (let offset = 0; offset < records.length; offset += CHUNK_ROWS) {
  const slice = records.slice(offset, offset + CHUNK_ROWS);
  const startRow = FIRST_DATA_ROW + offset;
  chunks.push({
    chunk_index: chunks.length + 1,
    chunk_rows: slice.length,
    start_row: startRow,
    request_body: {
      valueInputOption: 'RAW',
      data: [{ range: `${TAB_NAME}!A${startRow}`, majorDimension: 'ROWS', values: slice }],
    },
  });
}

return chunks.map((c) => ({ json: { ...c, chunk_total: chunks.length } }));

const source = $('Code - Map Roster To Sheet Columns').first().json;
const chunks = $('Code - Build Sheets Write Chunks').all();

return [{ json: {
  status: 'SUCCESS',
  spreadsheet_id: '1w-PBwKVwLoqQ7tF22baZFKAvb-Gn6f29Brwv1OdIPf4',
  spreadsheet_name: 'Org Broswer N8N Refresh Mondays',
  tab_name: 'Sheet1',
  scope: 'Frontline org - active employees at or under workgroup 12056',
  employee_row_count: source.row_count,
  sheet_column_count: source.column_count,
  header_row_preserved: true,
  columns_populated: source.headers_filled,
  columns_left_blank: source.headers_left_blank,
  sheets_write_requests_used: chunks.length + 1,
  schedule: 'Mondays 04:00 America/Phoenix (Arizona, no DST) = 11:00 UTC',
} }];
